#!/usr/bin/env bash
# Apply WireGuard config for comm_benchmark cross-PC measurement.
# Run on PC b or PC c. Usage:
#   bash apply_wg.sh b    # for PC b
#   bash apply_wg.sh c    # for PC c
#
# Requirements:
#   - wireguard installed (sudo apt install -y wireguard)
#   - /etc/wireguard/<host>_priv exists (generated by `wg genkey`)
#
# What it does:
#   1) Copy network/wg0.<host>.conf to /etc/wireguard/wg0.conf
#   2) Substitute the __PASTE_<HOST>_PRIV_HERE__ placeholder with the
#      actual private key from /etc/wireguard/<host>_priv
#   3) chmod 600
#   4) wg-quick up wg0
#   5) Show handshake status

set -e

HOST="${1:-}"
case "$HOST" in
  b|c) ;;
  *) echo "Usage: $0 b|c" >&2; exit 1 ;;
esac

SRC_CONF="$(dirname "$0")/wg0.${HOST}.conf"
DST_CONF="/etc/wireguard/wg0.conf"
PRIV_FILE="/etc/wireguard/${HOST}_priv"

if [[ ! -f "$SRC_CONF" ]]; then
  echo "Config not found: $SRC_CONF" >&2; exit 1
fi
if [[ ! -f "$PRIV_FILE" ]]; then
  echo "Private key not found: $PRIV_FILE" >&2
  echo "Generate first:" >&2
  echo "  sudo sh -c 'wg genkey | tee $PRIV_FILE | wg pubkey > /etc/wireguard/${HOST}_pub'" >&2
  exit 1
fi

# Tear down existing wg0 if any (idempotent re-run)
sudo wg-quick down wg0 2>/dev/null || true

# Copy + substitute
sudo cp "$SRC_CONF" "$DST_CONF"
PRIV_VALUE=$(sudo cat "$PRIV_FILE")
sudo sed -i "s|__PASTE_${HOST^^}_PRIV_HERE__|${PRIV_VALUE}|" "$DST_CONF"
sudo chmod 600 "$DST_CONF"

# Bring up
sudo wg-quick up wg0

echo
echo "=== wg show ==="
sudo wg show wg0

echo
echo "=== expected: 'latest handshake' should appear within 30 s ==="
echo "    if not, peer pubkey may be wrong (see network/README.md)"
